def f(g):
    h=len(g); w=len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    C=max((c for c in cnt if c), key=lambda c:cnt[c])
    N=[c for c,v in cnt.items() if c not in (0,C)][0]
