    def colnoise(c): return any(g[r][c]==N for r in range(h))
    # horizontal treatment of block rows
    for r in Br:
        if not rownoise(r):
            for c in range(w): paint(r,c,C)
        else:
            left_noise = any(g[r][c]==N for c in range(w) if c<min(Bc))
            right_noise = any(g[r][c]==N for c in range(w) if c>max(Bc))
            if left_noise and not right_noise:
                for c in range(max(Bc)+1,w): paint(r,c,C)
            elif right_noise and not left_noise:
                for c in range(min(Bc)-1,-1,-1): paint(r,c,C)
            else:
                continue  # keep only block cells
    # vertical
    for c in Bc:
        if not colnoise(c):
            for r in range(h): paint(r,c,C)
        else:
            up_noise = any(g[r][c]==N for r in range(h) if r<min(Br))
            dn_noise = any(g[r][c]==N for r in range(h) if r>max(Br))
            if up_noise and not dn_noise:
                for r in range(min(Br)): paint(r,c,C)
            elif dn_noise and not up_noise:
                for r in range(max(Br)+1,h): paint(r,c,C)
            else:
                continue
    return out

