    br0,br1=min(Br),max(Br); bc0,bc1=min(Bc),max(Bc)
    out=[[g[r][c] for c in range(w)] for r in range(h)]
    def pn(r,c): return g[r][c]==N
    # vertical stripes: extend AWAY from noise on the line
    for c in Bc:
        up = any(pn(r,c) for r in range(br0)); dn = any(pn(r,c) for r in range(br1+1,h))
        if up and dn: continue
        if up and not dn:   # noise above -> extend down
            for r in range(br1+1,h):
                if g[r][c]!=N: out[r][c]=C
        elif dn and not up: # noise below -> extend up
            for r in range(br0):
                if g[r][c]!=N: out[r][c]=C
        else:              # clean -> both
            for r in range(h):
                if g[r][c]!=N: out[r][c]=C
    # horizontal stripes on block rows
    for r in Br:
        ln = any(pn(r,c) for c in range(bc0)); rt = any(pn(r,c) for c in range(bc1+1,w))
        if ln and rt: continue
        if ln and not rt:   # noise left -> extend right
            for c in range(bc1+1,w):
                if g[r][c]!=N: out[r][c]=C
        elif rt and not ln: # noise right -> extend left
            for c in range(bc0):
                if g[r][c]!=N: out[r][c]=C
        else:
            for c in range(w):
                if g[r][c]!=N: out[r][c]=C
    return out
